#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=7

UNITY_VERSION=6000.3.2f1
UNITY_CHANGESET=a9779f353c9b
DDK_MODULES=(windows-il2cpp windows-server android android-sdk-ndk-tools android-open-jdk-17.0.9+9)
REPO_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd -P)"

# The DDK is Windows-only: every action runs in Windows PowerShell through tools/wizard-helper.ps1,
# from Git Bash (cygpath) or WSL (wslpath). Paths handed to the helper are always Windows paths.
if command -v cygpath >/dev/null 2>&1; then
  to_win() { cygpath -w "$1"; }; to_unix() { cygpath -u "$1"; }
elif command -v wslpath >/dev/null 2>&1; then
  to_win() { wslpath -w "$1"; }; to_unix() { wslpath -u "$1"; }
else
  printf '\n  The Dreamscape DDK only runs on Windows: run this wizard from Git Bash or WSL on Windows.\n'
  printf '  To install only the agent skills on this machine, run: %s/install.sh\n\n' "$REPO_DIR"
  exit 1
fi
if ! command -v powershell.exe >/dev/null 2>&1; then
  printf '\n  powershell.exe is not on PATH, so this wizard cannot reach Windows.\n\n'
  exit 1
fi
HELPER="$(to_win "$REPO_DIR/tools/wizard-helper.ps1")"
if [[ "$HELPER" == '\\'* ]]; then
  printf '\n  This clone is on the WSL file system (%s).\n' "$HELPER"
  printf '  Windows junctions cannot point there: clone the repo onto a Windows drive (under /mnt/c/ etc.) and re-run.\n\n'
  exit 1
fi

# helper CMD ARGS... runs a helper subcommand; its output streams to the terminal.
helper() {
  ( cd "$REPO_DIR" && MSYS_NO_PATHCONV=1 MSYS2_ARG_CONV_EXCL='*' \
      powershell.exe -NoProfile -ExecutionPolicy Bypass -File "$HELPER" "$@" )
}
# value CMD ARGS... prints the one-line answer of a value subcommand (empty when not found or on error).
value() { local v; v="$(helper "$@" </dev/null 2>/dev/null | tr -d '\r' | tail -n 1)" || true; printf '%s' "$v"; }
# has_count CMD DIR MIN: true when the helper counts at least MIN matching .tgz files in DIR.
has_count() { local n; n="$(value "$1" "$2")"; [[ "$n" =~ ^[0-9]+$ ]] && (( n >= $3 )); }
# win_path INPUT: drops quotes and trailing backslashes, and turns /c/... or /mnt/c/... into C:\...
win_path() {
  local p="$1"
  p="${p#\"}"; p="${p%\"}"; p="${p#\'}"; p="${p%\'}"
  if [[ "$p" == /* ]]; then p="$(to_win "$p")"; fi
  while [[ ${#p} -gt 3 && "$p" == *'\' ]]; do p="${p%\\}"; done
  printf '%s' "$p"
}

PROFILE_WIN="$(value profile-dir)"
if [[ -z "$PROFILE_WIN" ]]; then
  printf '\n  Windows PowerShell did not answer (%s profile-dir).\n\n' "$HELPER"
  exit 1
fi
LOCAL_WIN="$(value local-dir)"; [[ -n "$LOCAL_WIN" ]] || LOCAL_WIN="$PROFILE_WIN\\AppData\\Local"
CONFIG_WIN="$PROFILE_WIN\\.dreamscape-ddk\\config.env"
ENV_FILE="$(to_unix "$PROFILE_WIN")/.dreamscape-ddk/config.env"
mkdir -p "$(dirname "$ENV_FILE")"
TEMP_WIN="$(value temp-dir)"
LOG_FILE=/dev/null; [[ -n "$TEMP_WIN" ]] && LOG_FILE="$(to_unix "$TEMP_WIN")/dreamscape-ddk-wizard.jsonl"
RUN_ID="wiz$(date +%s)$$"
# wlog LEVEL EVENT DETAIL appends one JSONL record to the log the helper also writes.
wlog() {
  local d="${3:-}"; d="${d//\\/\\\\}"; d="${d//\"/\\\"}"
  printf '{"ts":"%s","run_id":"%s","level":"%s","event":"%s","loc":"setup-wizard.sh","ctx":{"detail":"%s"}}\n' \
    "$(date -u +%Y-%m-%dT%H:%M:%SZ)" "$RUN_ID" "$1" "$2" "$d" >> "$LOG_FILE" 2>/dev/null || true
}
wlog info start "$REPO_DIR"

banner "Dreamscape DDK: guided setup"

# -- 1 ----------------------------------------------------------------------
stage "Agent skills for Claude Code and Codex"
say "Installs the dreamscape-ddk skills, so your coding agent knows the working path around the DDK's bugs."
note "Codex reads %USERPROFILE%\\.agents\\skills and Claude Code reads %USERPROFILE%\\.claude\\skills."
note "The skills are linked to this clone: a 'git pull' here updates them."
while :; do
  ask DDK_AGENTS "Install for which agents? both, claude or codex [both]:"
  DDK_AGENTS="${DDK_AGENTS:-both}"
  case "$DDK_AGENTS" in both|claude|codex) break ;; *) warn "type both, claude or codex" ;; esac
done
write_env DDK_AGENTS "$DDK_AGENTS"
if helper install-skills -Agent "$DDK_AGENTS"; then
  wlog info skills_installed "$DDK_AGENTS"
else
  warn "Some skill folders already exist and this installer did not create them (FAIL lines above)."
  if confirm "Replace them? Old folders are renamed to <name>.bak-<time>; old links are removed, not their targets."; then
    if helper install-skills -Agent "$DDK_AGENTS" -Force; then wlog info skills_installed_force "$DDK_AGENTS"
    else SKIPPED+=("agent skills: install.ps1 failed, see %TEMP%\\dreamscape-ddk-skills-install.jsonl"); fi
  else
    SKIPPED+=("agent skills: existing folders left alone (install.ps1 -Force replaces them)")
  fi
fi
pause

# -- 2 ----------------------------------------------------------------------
stage "Unity CLI"
UNITY_CLI="$(value unity-cli)"
if [[ -n "$UNITY_CLI" ]]; then
  say "Found the Unity CLI: $UNITY_CLI"
else
  say "The Unity CLI installs the editor, signs you in and activates your license from the command line."
  say "Unity's official installer puts it in %LOCALAPPDATA%\\Unity\\bin."
  note "It runs, in PowerShell: irm https://unity.com/install.ps1 | iex"
  if confirm "Install the Unity CLI now?"; then
    helper install-unity-cli || true
    UNITY_CLI="$(value unity-cli)"
  fi
  if [[ -n "$UNITY_CLI" ]]; then
    say "Installed: $UNITY_CLI"
  else
    warn "No Unity CLI, so stages 3 and 4 are skipped."
    SKIPPED+=("Unity CLI: irm https://unity.com/install.ps1 | iex (PowerShell), then re-run this wizard")
  fi
fi
wlog info unity_cli "${UNITY_CLI:-missing}"
pause

# -- 3 ----------------------------------------------------------------------
stage "Unity sign-in and license"
if [[ -z "$UNITY_CLI" ]]; then
  warn "Skipped: no Unity CLI (stage 2)."
else
  if [[ "$(value auth-ok "$UNITY_CLI")" == yes ]]; then
    say "You are signed in to Unity."
  else
    say "Sign in with your Unity ID. Your browser opens on Unity's sign-in page."
    step "Sign in there (or create a free Unity ID), then come back to this window."
    note "Your credentials stay in the Unity CLI's own keyring. This wizard never sees or stores them."
    pause "Press Enter to open the Unity sign-in"
    helper auth-login "$UNITY_CLI" || true
    if [[ "$(value auth-ok "$UNITY_CLI")" == yes ]]; then
      say "Signed in."
    else
      warn "Still not signed in."
      SKIPPED+=("Unity sign-in: unity auth login")
    fi
  fi
  wlog info unity_auth "$(value auth-ok "$UNITY_CLI")"
  if [[ "$(value license-ok "$UNITY_CLI")" == yes ]]; then
    say "A Unity license is active."
  else
    say "No active Unity license was found. Unity needs one to open and build DDK projects."
    step "personal  the free Unity Personal license (check that you are eligible under Unity's terms)"
    step "serial    a Unity Pro, Plus, Industry or Enterprise serial number"
    step "skip      you will activate a license in Unity Hub instead"
    while :; do
      ask LICENSE_KIND "personal, serial or skip:"
      case "$LICENSE_KIND" in personal|serial|skip) break ;; *) warn "type personal, serial or skip" ;; esac
    done
    wlog info license_choice "$LICENSE_KIND"
    if [[ "$LICENSE_KIND" == personal ]]; then
      if confirm "Activate Unity Personal? This accepts the Unity Personal license terms."; then
        helper license-activate "$UNITY_CLI" personal || true
      fi
    elif [[ "$LICENSE_KIND" == serial ]]; then
      note "The serial goes to the Unity CLI once. It is not saved or logged."
      ask_secret UNITY_SERIAL "Paste your serial (input hidden):"
      export DDK_UNITY_SERIAL="$UNITY_SERIAL"
      export WSLENV="${WSLENV:+$WSLENV:}DDK_UNITY_SERIAL"
      helper license-activate "$UNITY_CLI" serial || true
      unset DDK_UNITY_SERIAL; UNITY_SERIAL=""
    fi
    if [[ "$(value license-ok "$UNITY_CLI")" == yes ]]; then
      say "License active."
    else
      warn "No active license yet."
      SKIPPED+=("Unity license: unity license activate --personal --accept-eula (or --serial), or use Unity Hub")
    fi
  fi
fi
pause

# -- 4 ----------------------------------------------------------------------
stage "Unity $UNITY_VERSION and its build modules"
if [[ -z "$UNITY_CLI" ]]; then
  warn "Skipped: no Unity CLI (stage 2)."
else
  EDITOR_EXE="$(value editor-exe "$UNITY_CLI" "$UNITY_VERSION")"
  if [[ -z "$EDITOR_EXE" ]]; then
    say "The DDK needs exactly Unity $UNITY_VERSION (changeset $UNITY_CHANGESET) with these modules:"
    note "${DDK_MODULES[*]}"
    say "It is a multi-GB download and can take a long time. Windows may ask for admin rights."
    if confirm "Install Unity $UNITY_VERSION now? This accepts the module license agreements."; then
      wlog info install_editor "$UNITY_VERSION"
      helper install-editor "$UNITY_CLI" "$UNITY_VERSION" "$UNITY_CHANGESET" "${DDK_MODULES[@]}" || true
      EDITOR_EXE="$(value editor-exe "$UNITY_CLI" "$UNITY_VERSION")"
    fi
  fi
  if [[ -n "$EDITOR_EXE" ]]; then
    say "Editor: $EDITOR_EXE"
    MISSING="$(value missing-modules "$EDITOR_EXE")"
    if [[ -n "$MISSING" ]]; then
      warn "Missing modules: $MISSING"
      if confirm "Install the missing modules now?"; then
        read -r -a MISSING_IDS <<< "$MISSING"
        helper install-modules "$UNITY_CLI" "$UNITY_VERSION" "${MISSING_IDS[@]}" || true
        MISSING="$(value missing-modules "$EDITOR_EXE")"
      fi
      if [[ -n "$MISSING" ]]; then
        SKIPPED+=("Unity modules: unity install-modules --editor-version $UNITY_VERSION --module <id> --accept-eula, for: $MISSING")
      fi
    else
      say "All DDK modules are installed."
    fi
    write_env DDK_UNITY_EXE "$EDITOR_EXE"
  else
    warn "Unity $UNITY_VERSION is not installed."
    SKIPPED+=("Unity $UNITY_VERSION: re-run this wizard, or use the unity-editor fix line from ddk-doctor.ps1")
  fi
fi
wlog info unity_editor "${EDITOR_EXE:-missing}"
pause

# -- 5 ----------------------------------------------------------------------
stage "C++ build tools and Python"
VC="$(value vc-path)"
if [[ -n "$VC" ]]; then
  say "C++ build tools: $VC"
else
  say "IL2CPP builds need the Visual Studio 2022 C++ build tools. Build Tools are enough, no full Visual Studio."
  BT="$(value buildtools-path)"
  if [[ -n "$BT" ]]; then
    say "Build Tools are installed at $BT, but without the C++ workload."
    if confirm "Add the C++ workload and Windows SDK 22621 with the Visual Studio Installer? (admin prompt, several GB)"; then
      helper modify-buildtools "$BT" || true
    fi
  elif confirm "Install VS 2022 Build Tools with the C++ workload through winget? (admin prompt, several GB)"; then
    helper install-buildtools || true
  fi
  VC="$(value vc-path)"
  if [[ -n "$VC" ]]; then
    say "C++ build tools: $VC"
  else
    warn "The C++ build tools are still missing."
    SKIPPED+=("VS 2022 Build Tools with the C++ workload: see the msvc-toolchain fix line from ddk-doctor.ps1")
  fi
fi
wlog info msvc "${VC:-missing}"
if [[ "$(value python-ok)" == yes ]]; then
  say "Python 3.12 or newer: found."
else
  say "The skill scripts need Python 3.12 or newer on PATH (the Microsoft Store alias does not count)."
  if confirm "Install Python 3.12 through winget (per-user, added to PATH)?"; then
    helper install-python || true
  fi
  if [[ "$(value python-ok)" == yes ]]; then
    say "Python installed. Open a new terminal before you use it outside this wizard."
  else
    warn "Python is still missing."
    SKIPPED+=("Python 3.12+: winget install Python.Python.3.12, then open a new terminal")
  fi
fi
wlog info python "$(value python-ok)"
pause

# -- 6 ----------------------------------------------------------------------
stage "DDK packages and templates"
say "Projects are built from the DDK's 55 com.dreamscape-learn.*.tgz packages and its template .tgz files."
note "They come from your own licensed DDK installer. Keep them private: vendor package.json files embed a CI token."
TARBALLS=""; TEMPLATES=""
CUR_T="$(_existing DDK_TARBALL_DIR || true)"; CUR_M="$(_existing DDK_TEMPLATE_DIR || true)"
if [[ -n "$CUR_T" ]] && has_count count-tgz "$CUR_T" 55; then
  say "Saved by an earlier run: $CUR_T"
  if confirm "Keep using it?"; then TARBALLS="$CUR_T"; TEMPLATES="$CUR_M"; fi
fi
if [[ -z "$TARBALLS" ]]; then
  FOUND="$(value ddk-default)"
  if [[ -n "$FOUND" ]]; then
    say "Found an installed DDK: ${FOUND%%|*}"
    if confirm "Use it?"; then TARBALLS="${FOUND%%|*}"; TEMPLATES="${FOUND#*|}"; fi
  fi
fi
if [[ -z "$TARBALLS" ]]; then
  say "Where should the packages come from?"
  step "installer  the DDK installer .exe (dreamscape-developer-kit-*.exe): the wizard unpacks it"
  step "folder     a folder that already holds the 55 com.dreamscape-learn.*.tgz files"
  step "skip       do this later"
  while :; do
    ask DDK_SOURCE "installer, folder or skip:"
    case "$DDK_SOURCE" in installer|folder|skip) break ;; *) warn "type installer, folder or skip" ;; esac
  done
  wlog info ddk_source "$DDK_SOURCE"
  if [[ "$DDK_SOURCE" == folder ]]; then
    ask PKG_DIR "Folder with the .tgz files (paste the path, or drag the folder here):"
    PKG_DIR="$(win_path "$PKG_DIR")"
    if has_count count-tgz "$PKG_DIR" 55; then
      TARBALLS="$PKG_DIR"
      if has_count count-templates "$PKG_DIR" 1; then
        TEMPLATES="$PKG_DIR"
      else
        ask TPL_DIR "Folder with the template.*.tgz files (Enter to skip):"
        TPL_DIR="$(win_path "$TPL_DIR")"
        if [[ -n "$TPL_DIR" ]]; then TEMPLATES="$TPL_DIR"; fi
      fi
    else
      warn "Found $(value count-tgz "$PKG_DIR") of 55 packages in $PKG_DIR."
    fi
  elif [[ "$DDK_SOURCE" == installer ]]; then
    ask DDK_INSTALLER "Path to dreamscape-developer-kit-*.exe (paste it, or drag the file here):"
    DDK_INSTALLER="$(win_path "$DDK_INSTALLER")"
    if [[ "$(value path-exists "$DDK_INSTALLER")" != yes ]]; then
      warn "Not found: $DDK_INSTALLER"
    else
      write_env DDK_INSTALLER "$DDK_INSTALLER"
      VER="${DDK_INSTALLER##*\\}"; VER="${VER%.exe}"; VER="${VER#dreamscape-developer-kit-}"; VER="${VER//[^A-Za-z0-9._-]/_}"
      DEST="$LOCAL_WIN\\dreamscape-ddk\\$VER"
      MISS="$(value extract-tools-missing)"
      if [[ -n "$MISS" ]]; then
        say "Unpacking the installer needs: $MISS"
        note "dotnet = .NET 8 SDK (winget), wix = WiX 6 CLI (dotnet tool), lessmsi (winget)"
        if confirm "Install them now?"; then
          read -r -a MISS_IDS <<< "$MISS"
          helper install-extract-tools "${MISS_IDS[@]}" || true
        fi
        MISS="$(value extract-tools-missing)"
      fi
      if [[ -n "$MISS" ]]; then
        warn "Still missing: $MISS"
        SKIPPED+=("unpacking tools: $MISS (then re-run this wizard)")
      elif [[ "$(value python-ok)" != yes ]]; then
        warn "Unpacking also needs Python (stage 5)."
        SKIPPED+=("Python 3.12+, then re-run this wizard to unpack the installer")
      else
        say "The installer is unpacked to $DEST"
        note "That takes about 3 GB of disk and several minutes."
        if confirm "Unpack it now?"; then
          wlog info extract_installer "$DEST"
          TMP_OUT="$(mktemp)"
          helper extract-installer "$DDK_INSTALLER" "$DEST" 2>&1 | tr -d '\r' | tee "$TMP_OUT" || true
          RESULT="$(grep '^RESULT|' "$TMP_OUT" | tail -n 1 || true)"; rm -f "$TMP_OUT"
          RESULT="${RESULT#RESULT|}"
          if [[ -n "$RESULT" ]] && has_count count-tgz "${RESULT%%|*}" 55; then
            TARBALLS="${RESULT%%|*}"; TEMPLATES="${RESULT#*|}"
          else
            warn "The unpacked tree has no complete package set. Details: $DEST\\notes\\extract.jsonl"
          fi
        fi
      fi
    fi
  fi
fi
if [[ -n "$TARBALLS" ]]; then
  write_env DDK_TARBALL_DIR "$TARBALLS"
  if [[ -n "$TEMPLATES" ]] && has_count count-templates "$TEMPLATES" 1; then
    write_env DDK_TEMPLATE_DIR "$TEMPLATES"
  else
    warn "No template .tgz found, so new projects cannot start from a DDK template."
    SKIPPED+=("DDK templates: re-run this wizard with the DDK installer .exe")
  fi
else
  SKIPPED+=("DDK packages: re-run this wizard with your DDK installer .exe or a folder of the 55 .tgz files")
fi
wlog info ddk_packages "${TARBALLS:-missing}"
pause

# -- 7 ----------------------------------------------------------------------
stage "Health check"
say "Runs ddk-doctor.ps1 with the values saved in $CONFIG_WIN"
printf '\n'
if helper doctor; then
  printf '\n'; say "Ready to build."
  wlog info doctor ready
else
  printf '\n'; warn "Some required checks failed. Each FAIL line above has its fix."
  SKIPPED+=("ddk-doctor.ps1: fix its FAIL lines, then re-run this wizard")
  wlog warn doctor not_ready
fi
pause

finish
printf '  %sUse the skills%s\n' "$BOLD" "$RESET"
step "Restart open Claude Code and Codex sessions so they load the skills."
step "Claude Code: describe the DDK task (dreamscape-ddk loads on its own) or type /dreamscape-ddk."
step "Codex: \$dreamscape-ddk for DDK work."
step "New DDK release: /dreamscape-ddk-re (Claude Code) or \$dreamscape-ddk-re (Codex)."
note "Saved settings: $CONFIG_WIN. Re-run this wizard any time; it keeps what is already done."
note "Log: ${TEMP_WIN:-%TEMP%}\\dreamscape-ddk-wizard.jsonl"
printf '\n'
wlog info done "skipped=${#SKIPPED[@]}"
}

run_wizard "$@"; exit
